import { useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

type ThemeValue = 'light' | 'dark' | 'system';

export interface AppearanceSettings {
  theme: ThemeValue;
  scale: number;
  compact: boolean;
  fontFamily: string;
}

export interface AppearanceSettingsScreenProps {
  value?: AppearanceSettings;
  defaultValue?: AppearanceSettings;
  onChange?: (value: AppearanceSettings) => void;
}

const THEME_ITEMS = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const THEME_LABELS: Record<ThemeValue, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const FONT_OPTIONS = [
  { value: 'sans', label: 'Inter Tight', meta: 'по умолчанию' },
  { value: 'display', label: 'Fraunces' },
  { value: 'mono', label: 'JetBrains Mono' },
];

const INITIAL: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  compact: false,
  fontFamily: 'sans',
};

export default function AppearanceSettingsScreen({
  value,
  defaultValue,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [internal, setInternal] = useState<AppearanceSettings>(defaultValue ?? INITIAL);
  const settings = value ?? internal;

  const update = (patch: Partial<AppearanceSettings>) => {
    const next = { ...settings, ...patch };
    if (value === undefined) setInternal(next);
    onChange?.(next);
  };

  return (
    <div style={{ display: 'grid', gap: '20px', maxWidth: '520px' }}>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '12px',
        }}
      >
        <h2 style={{ margin: 0, font: 'inherit', fontFamily: 'var(--jx-font-display)', fontSize: '20px' }}>
          Внешний вид
        </h2>
        <JxBadge tone="accent" dot>
          {THEME_LABELS[settings.theme]}
        </JxBadge>
      </div>

      <div style={{ display: 'grid', gap: '8px' }}>
        <span style={{ color: 'var(--jx-text-2)' }}>Тема оформления</span>
        <JxToggle
          items={THEME_ITEMS}
          value={settings.theme}
          onValueChange={(theme) => update({ theme: theme as ThemeValue })}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={5}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(scale) => update({ scale })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.compact}
        onChange={(event) => update({ compact: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        placeholder="Выберите шрифт"
        options={FONT_OPTIONS}
        value={settings.fontFamily}
        onValueChange={(fontFamily) => update({ fontFamily })}
      />
    </div>
  );
}

